// Vulnerable 'immutable' attempt:
// 1. Class is non-final (can be subclassed with mutable state).
// 2. Mutable reference escapes directly via getter without defensive copy.
import java.util.Date;

public class Period {
    private final Date start;
    private final Date end;

    public Period(Date start, Date end) {
        if (start.compareTo(end) > 0)
            throw new IllegalArgumentException(start + " after " + end);
        this.start = start; // Flaw: stores direct reference!
        this.end = end;
    }

    public Date getStart() { return start; } // Flaw: leaks internal mutable Date!
    public Date getEnd()   { return end; }
}

