import java.util.Date;

public class Main {
    public static void main(String[] args) {
        Date start = new Date();
        Date end = new Date();
        Period p = new Period(start, end);

        end.setYear(78); // Does not affect p!
        p.getEnd().setYear(85); // Does not affect p!
        System.out.println(p.getEnd()); // Preserved untouched!
    }
}
